-- =============================================================================
-- PDI · 0045 · Mapa de origen por municipio (Diversidad, Equidad e Inclusión)
--
-- GENERADO por scripts/build-mapa-origen.py a partir de los microdatos de bi/.
-- No editar a mano: cambiar el script y volver a generar.
--
-- Fuente: caracterizacion multicampus.xlsx, columna «CIUDAD DE ORIGEN». 6128 de 6657 registros
-- ubicados en 254 municipios. Celdas con menos de 5 estudiantes
-- guardadas como reservadas: 706.
--
-- Requiere 0041 y 0044. Idempotente.
-- =============================================================================

values ((select id from public.od_reports where slug = 'diversidad-equidad-inclusion' and period_id = (select id from public.od_periods where label = '2020-2025')), 'origen-municipio', 'De dónde vienen los estudiantes',
  'Según la caracterización estudiantil multicampus: calor por departamento de origen y, al acercarse, un punto por municipio. La base es quien respondió la encuesta ese año. Menos de 5 se publica como «< 5».',
  'municipio', 'estudiantes', (select id from public.od_offices where name = 'Bienestar Universitario'),
  '{2022,2023,2024,2025}'::smallint[], 1)
on conflict (report_id, key) do update
  set title = excluded.title, description = excluded.description, mode = excluded.mode,
      unit = excluded.unit, office_id = excluded.office_id, years = excluded.years;

delete from public.od_map_values where map_id = (select id from public.od_maps where key = 'origen-municipio' and report_id = (select id from public.od_reports where slug = 'diversidad-equidad-inclusion' and period_id = (select id from public.od_periods where label = '2020-2025')));
